def move_private_material(apps,schema_editor):
    Round=apps.get_model('capsule','Round')
    Secrets=apps.get_model('capsule','RoundSecrets')
    Event=apps.get_model('capsule','Event')
    import hashlib,json
    def digest(obj):
        return hashlib.sha256(json.dumps(obj,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode()).hexdigest()
    for r in Round.objects.using(schema_editor.connection.alias).iterator():
        Secrets.objects.using(schema_editor.connection.alias).create(round_id=r.pk,withheld=r.withheld,calibration={})
        Round.objects.using(schema_editor.connection.alias).filter(pk=r.pk).update(protocol='0.1')
        previous=''
        for event in Event.objects.using(schema_editor.connection.alias).filter(round_id=r.pk).order_by('id'):
            value=digest({'round':str(r.pk),'actor':event.actor_id,'kind':event.kind,'detail':event.detail,
                'timestamp':event.created_at.isoformat(),'previous_hash':previous})
            Event.objects.using(schema_editor.connection.alias).filter(pk=event.pk).update(previous_hash=previous,hash=value)
            previous=value

def restore_private_material(apps,schema_editor):
    Round=apps.get_model('capsule','Round');Secrets=apps.get_model('capsule','RoundSecrets')
    for row in Secrets.objects.using(schema_editor.connection.alias).iterator():
        Round.objects.using(schema_editor.connection.alias).filter(pk=row.round_id).update(withheld=row.withheld)

